#!/usr/bin/python3
import json, os, tempfile, threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlparse

PORT=8347
STATE_DIR=Path("/var/lib/harbor-service")
STATE_FILE=STATE_DIR/"state.json"
SEED_FILE=Path(__file__).with_name("seed.json")
LOCK=threading.Lock()

def load_state():
    with STATE_FILE.open(encoding="utf-8") as f: return json.load(f)

def save_state(state):
    fd,tmp=tempfile.mkstemp(prefix="state-",suffix=".json",dir=STATE_DIR)
    try:
        with os.fdopen(fd,"w",encoding="utf-8") as f:
            json.dump(state,f,indent=2,sort_keys=True); f.write("\n")
        os.replace(tmp,STATE_FILE)
    finally:
        if os.path.exists(tmp): os.unlink(tmp)

def find(items,key,value): return next((x for x in items if x.get(key)==value),None)

class Handler(BaseHTTPRequestHandler):
    server_version="RecallCoordinator/1.0"
    def log_message(self,*args): pass
    def reply(self,status,payload):
        body=json.dumps(payload,sort_keys=True).encode()
        self.send_response(status); self.send_header("Content-Type","application/json")
        self.send_header("Content-Length",str(len(body))); self.end_headers(); self.wfile.write(body)
    def body(self):
        try:
            value=json.loads(self.rfile.read(int(self.headers.get("Content-Length","0"))) or b"{}")
            if not isinstance(value,dict): raise ValueError
            return value
        except Exception as e: raise ValueError("invalid JSON object") from e
    def need(self,body,*keys):
        missing=[k for k in keys if not isinstance(body.get(k),str) or not body[k].strip()]
        if missing: raise ValueError("missing required string fields: "+", ".join(missing))
    def do_GET(self):
        route=urlparse(self.path).path
        if route=="/health": return self.reply(200,{"service":"recall-coordinator","status":"ready"})
        key={"/alerts":"alerts","/shipments":"shipments","/locations":"locations","/incidents":"incidents"}.get(route)
        if not key: return self.reply(404,{"error":"unknown endpoint"})
        with LOCK: self.reply(200,{key:load_state()[key]})
    def do_POST(self):
        try:
            body=self.body()
            with LOCK:
                state=load_state(); result=self.mutate(urlparse(self.path).path,body,state); save_state(state)
            self.reply(200,result)
        except ValueError as e: self.reply(400,{"error":str(e)})
    def mutate(self,route,b,state):
        if route=="/incidents":
            self.need(b,"incident_id","alert_id","owner","severity")
            if b["severity"] not in {"low","medium","high"}: raise ValueError("invalid severity")
            if find(state["incidents"],"incident_id",b["incident_id"]): raise ValueError("incident already exists")
            if not find(state["alerts"],"alert_id",b["alert_id"]): raise ValueError("alert not found")
            x={"incident_id":b["incident_id"],"alert_id":b["alert_id"],"owner":b["owner"],"severity":b["severity"],"status":"open","shipments":[],"notifications":[],"summary":""}
            state["incidents"].append(x); return {"created":x}
        if route=="/shipments/hold":
            self.need(b,"shipment_id","reason"); x=find(state["shipments"],"shipment_id",b["shipment_id"])
            if not x: raise ValueError("shipment not found")
            if x["status"]=="cancelled": raise ValueError("cancelled shipment cannot be held")
            x["hold_reason"]=b["reason"]; return {"held":b["shipment_id"],"reason":b["reason"]}
        self.need(b,"incident_id"); inc=find(state["incidents"],"incident_id",b["incident_id"])
        if not inc: raise ValueError("incident not found")
        if inc["status"]!="open": raise ValueError("incident is not open")
        if route=="/incidents/link":
            self.need(b,"shipment_id")
            if not find(state["shipments"],"shipment_id",b["shipment_id"]): raise ValueError("shipment not found")
            if b["shipment_id"] in inc["shipments"]: raise ValueError("shipment already linked")
            inc["shipments"].append(b["shipment_id"]); return {"incident_id":b["incident_id"],"linked":b["shipment_id"]}
        if route=="/incidents/notify":
            self.need(b,"location_id","message")
            if not find(state["locations"],"location_id",b["location_id"]): raise ValueError("location not found")
            if any(n["location_id"]==b["location_id"] for n in inc["notifications"]): raise ValueError("location already notified")
            note={"location_id":b["location_id"],"message":b["message"]}; inc["notifications"].append(note)
            return {"incident_id":b["incident_id"],"notification":note}
        if route=="/incidents/close":
            self.need(b,"summary"); inc["status"]="closed"; inc["summary"]=b["summary"]
            return {"closed":b["incident_id"],"summary":b["summary"]}
        raise ValueError("unknown endpoint")

def main():
    STATE_DIR.mkdir(parents=True,exist_ok=True)
    if not STATE_FILE.exists():
        with SEED_FILE.open(encoding="utf-8") as f: save_state(json.load(f))
    ThreadingHTTPServer(("127.0.0.1",PORT),Handler).serve_forever()

if __name__=="__main__": main()

